    static let photos = group(name: "photos", description: "Query photo metadata and export.", subcommands: [
        leaf(name: "permission", description: "Check Photos authorization (status only).", usage: "mpia photos permission", exitCodes: photosExit),
        leaf(name: "albums", description: "List photo albums.", usage: "mpia photos albums --format json",
