             outputSchema: "Page"),
        leaf(name: "query", description: "Query asset metadata.", usage: "mpia photos query [filters] --format json", exitCodes: photosExit, outputSchema: "Page"),
        leaf(name: "get", description: "Get one asset metadata.", usage: "mpia photos get --id <id> --format json",
