        leaf(name: "export", description: "Export one asset.", usage: "mpia photos export --id <id> --output <file>",
             params: [string("id", "Asset ID", required: true), string("output", "Output file", type: .file)], exitCodes: photosExit,
             outputSchema: "PhotoExportPayload"),
    ])

    static let notes = group(name: "notes", description: "Bounded Notes.app Automation access.", subcommands: [
