        leaf(name: "accounts", description: "List note accounts.", usage: "mpia notes accounts", exitCodes: notesExit, outputSchema: "ListResult"),
        leaf(name: "folders", description: "List note folders.", usage: "mpia notes folders [--account-id <id>] --format json",
             params: [string("account-id", "Account ID")], exitCodes: notesExit,
             outputSchema: "ListResult"),
        leaf(name: "query", description: "Query note metadata.", usage: "mpia notes query [filters] --format json", exitCodes: notesExit, outputSchema: "Page"),
        leaf(name: "get", description: "Get one note.", usage: "mpia notes get --id <id> [--body plain|html] --format json",
