        leaf(name: "edit-body", description: "Replace a note body.", usage: "mpia notes edit-body --id <id> --input note.json --dry-run|--apply",
             mutates: true, params: [string("id", "Note ID", required: true), string("input", "JSON file", type: .file)], exitCodes: notesExit, safety: dryRunApply,
