    static let shortcuts = group(name: "shortcuts", description: "Run and author shortcuts.", subcommands: [
        leaf(name: "permission", description: "Check Shortcuts Events consent (status only).", usage: "mpia shortcuts permission", exitCodes: shortcutsExit),
        leaf(name: "list", description: "List shortcuts.", usage: "mpia shortcuts list --format json",
