        leaf(name: "update", description: "Update a managed shortcut.", usage: "mpia shortcuts update --id <id> --input <file> --dry-run|--apply",
             mutates: true, params: [string("id", "Shortcut ID", required: true), string("input", ".cherri file", type: .file)], exitCodes: shortcutsExit, safety: dryRunApply),
        leaf(name: "author validate", description: "Validate .cherri source.", usage: "mpia shortcuts author validate --input <file>",
